import { FONT_FAMILY, FONT_WEIGHT, TYPE_SCALE } from './typography';
// chart.js не читає CSS: шрифт підписів береться звідси. Сімейство задає
// applyChartDefaults один раз, ролі — chartFont у конкретних опціях. Вага
// явна завжди: плагін анотацій за замовчуванням бере bold (700), а такої ваги
// немає — браузер то брав 600, то синтезував жирний, і знімки «плавали».
export const chartFont = (role, weight = 'regular') => ({
    family: FONT_FAMILY,
    size: TYPE_SCALE[role].size,
    lineHeight: TYPE_SCALE[role].line / TYPE_SCALE[role].size,
    weight: FONT_WEIGHT[weight],
});
// Налаштування глобальні для chart.js — змінюємо його власний обʼєкт.
export function applyChartDefaults({ font }) {
    Object.assign(font, {
        family: FONT_FAMILY, size: TYPE_SCALE.bodyS.size, weight: FONT_WEIGHT.regular,
    });
}
