import { useEffect, useState } from 'react';
import { FONT_WEIGHT, TYPE_SCALE } from '06_shared/constants/tokens';
// Canvas не чекає на вебшрифт: chart.js, намальований до завантаження Fira
// Sans, лишився б із запасним шрифтом до наступного оновлення даних. Тож
// графік зʼявляється, коли шрифт готовий і минула коротка пауза (у STATIC —
// без паузи, заради детермінізму знімків). Без FontFace API (jsdom) — лише
// пауза, і таймер стартує синхронно, як раніше.
const CHART_FONT = `${FONT_WEIGHT.regular} ${TYPE_SCALE.bodyS.size}px "Fira Sans"`;
export function useChartReady(delayMs = 150) {
    const [ready, setReady] = useState(false);
    useEffect(() => {
        let active = true;
        let timer;
        const start = () => {
            if (active)
                timer = setTimeout(() => setReady(true), __IS_STATIC__ ? 0 : delayMs);
        };
        if (typeof document !== 'undefined' && document.fonts) {
            document.fonts.load(CHART_FONT).then(start, start);
        }
        else {
            start();
        }
        return () => {
            active = false;
            if (timer)
                clearTimeout(timer);
        };
    }, [delayMs]);
    return ready;
}
