import { Ticks } from 'chart.js';
import { chartFont } from '06_shared/constants/tokens';
// Скільки підписів лишається на осях вузького графіка.
const TIME_TICKS = 4;
const VALUE_TICKS = 5;
// Від цього значення число скорочується до тисяч: 84 755,9 -> 84.8k.
const THOUSANDS_FROM = 10000;
// Мінімальний проміжок між сусідніми підписами осі часу.
const TIME_LABEL_GAP = 12;
// На стільки пікселів підпис значення піднято над своєю лінією сітки;
// удвічі більше місця лишається зверху графіка, щоб верхній не обрізався.
const LABEL_LIFT = 8;
const LABEL_HALO = 3;
function compactTick(value, index, ticks) {
    if (typeof value === 'number' && Math.abs(value) >= THOUSANDS_FROM) {
        return `${(value / 1000).toFixed(1)}k`;
    }
    const numeric = Ticks.formatters.numeric;
    return numeric.apply(this, [Number(value), index, ticks]);
}
// На телефоні графік завширшки ~250px: три осі з довгими підписами зʼїдали
// майже всю ширину, а від самих ліній лишалася смужка. Тож лишається одна
// вісь значень (y) з кількома короткими підписами всередині сітки, додаткові осі ховаються
// зовсім (їхні значення є в підказці за дотиком), а на осі часу — кілька
// дрібніших горизонтальних підписів. Самі шкали (min/max) не змінюються.
export function compactChartOptions(source, surface) {
    const options = source;
    if (!options.scales)
        return source;
    const scales = Object.fromEntries(Object.entries(options.scales).map(([id, scale]) => {
        if (id === 'x') {
            return [id, {
                    ...scale,
                    ticks: {
                        ...scale.ticks,
                        maxTicksLimit: TIME_TICKS,
                        maxRotation: 0,
                        // Підпис починається від своєї поділки: вісь значень тепер без
                        // власної ширини, і відцентрований перший підпис відсував би
                        // графік від лівого краю.
                        align: 'start',
                        autoSkipPadding: TIME_LABEL_GAP,
                        font: chartFont('caption'),
                    },
                }];
        }
        if (id === 'y') {
            return [id, {
                    ...scale,
                    grid: { ...scale.grid, drawTicks: false },
                    ticks: {
                        ...scale.ticks,
                        stepSize: undefined,
                        maxTicksLimit: VALUE_TICKS,
                        // Лише «круглі» поділки: межі шкали (min/max) як окремі підписи
                        // ставали впритул до сусідніх і накладалися на них.
                        includeBounds: false,
                        // Підписи — всередині графіка, над своєю лінією сітки й поверх
                        // серій: уся ширина лишається лініям.
                        mirror: true,
                        labelOffset: -LABEL_LIFT,
                        z: 1,
                        // Обведення кольором тла: підпис читається й там, де через
                        // нього проходить лінія серії.
                        textStrokeColor: surface,
                        textStrokeWidth: LABEL_HALO,
                        font: chartFont('caption'),
                        callback: compactTick,
                    },
                }];
        }
        return [id, { ...scale, display: false }];
    }));
    const legend = options.plugins?.legend;
    const plugins = legend?.labels
        ? { ...options.plugins, legend: { ...legend, labels: { ...legend.labels, boxWidth: 12 } } }
        : options.plugins;
    const padding = typeof options.layout?.padding === 'object' ? options.layout.padding : {};
    const layout = { ...options.layout, padding: { ...padding, top: LABEL_LIFT * 2 } };
    return { ...source, scales, plugins, layout };
}
